/** `images` are captions; picture n is /help/kb-<id>-<n>.jpg. */
export type Article = { id: string; category: string; title: string; body: string[]; images?: string[] };

export const ARTICLES: Article[] = [
  { id: "order-statuses", category: "Orders", title: "What each order status means", body: [
    "Draft: the sales rep is still building the order. It can be edited or deleted.",
    "Ready to pull: the order was sent to the warehouse and the pick ticket can be printed. Lines are locked.",
    "Pulled: the items were taken from stock (oldest lots first, or lots you chose). Stock counts drop at this point.",
    "Sent back to sales: Delivery/Order Management found a problem on a pulled order. Sales fixes the quantities and sends it on, and it returns to Pulled.",
    "Completed: Delivery/Order Management checked the returned pick ticket. Only completed orders can be invoiced.",
    "Invoiced: an invoice exists. If the invoice is voided, the order goes back to Completed.",
    "Cancelled: the order was cancelled before it was pulled, or sales denied a customer order (the customer sees the reason). Orders with payments recorded can't be cancelled until the payments are voided.",
    "The bar at the top of every order shows where it is. The step it is on is filled in, with who does the next job underneath.",
  ], images: ["The step bar on an order that is Pulled and waiting for Delivery/Order Management."] },
  { id: "roles", category: "Orders", title: "Who can do what", body: [
    "Admin can do everything, including adding users and the web store connection.",
    "Sales can create and edit orders, set MUST CHECK, send orders to pull, invoice, take payments and manage customers.",
    "Warehouse can mark orders pulled, record returns, move and count stock, and edit the shop floor plan.",
    "Staff manage products, vendors, purchase orders and receiving.",
    "Delivery/Order Management marks pulled orders Completed (or sends them back), creates and voids invoices, and builds delivery routes.",
    "Routing: Delivery/Order Management, warehouse and admins can change routes. Everyone else can look at them.",
    "Customer is for a shop that orders from you. A customer login only gets the Shop page and their own display settings. See Customer logins and the shop. This is separate from the Staff role.",
    "Everyone signed in and active can read orders, stock and use Messages.",
  ] },
  { id: "customer-logins", category: "Orders", title: "Customer logins, the shop and the sales catalog", body: [
    "A customer with a login can browse your items, see their own prices and add things to a cart. The cart is saved on their account, so it is still there next time they sign in. When they place it, it becomes a draft sales order that sales approves. See Shopping cart and order summary. They cannot see anything else in the system.",
    "Before a login can be set up the customer needs a name, an address, a phone number, a route and a sales rep. The route is one to three letters, such as NOR, and groups deliveries. The rep is the sales person who looks after that customer. Usual payment is optional: leave it on Ask on each order and the customer picks cash, card or check every time.",
    "Two discounts, kept separate. The sales discount % comes off every price. The cash discount % only applies when an order is paid in cash. Both are set on the customer page by sales or an admin.",
    "Setting up a login takes two people. Sales or an admin opens Customer logins, picks the customer, types the person's name, a username and a password, and presses Create login. Give the username and password to the customer. They sign in with just those on the login page. Staff keep signing in with their email.",
    "A different sales person or admin then presses Verify on the same row. To change a password, type a new one on the row and press Set. Nobody can verify a login they set up themselves. Until it is verified the customer cannot shop. Remove takes the access away again.",
    "Prices a customer sees come from, in order: a price set just for them, otherwise the tier price (or the usual markup) less the customer's Discount %. Set the discount on the customer page. They also see the exact number available, which is stock on hand less what is already waiting on confirmed orders.",
    "The Sales catalog is the same list for staff. Pick a customer and each item shows what they would pay. Type a price under This customer only to give them a special price, or under the tier price to change it for everyone in that tier. Leave a box empty to go back to the normal price. Add items to the cart and press Create draft order.",
    "Open orders lists every order a customer sent in, with the assigned rep shown on each. The rep also sees a number beside Open orders in the menu. Press Approve to send it to be pulled, Edit to change it first, or Deny and type a reason. The customer sees Denied with your reason. Until you decide, they see Waiting for approval.",
    "On the shop page a customer sees their orders with the items on each. Buy again shows things they have ordered before, and Add these to the cart copies a past order into the cart.",
    "Each shop has its own login. A login only ever orders for the shop it was made for, so set one up for every shop that orders from you, even when one person looks after several.",
  ], images: ["Create the login here with a username and password. The customer account must already have a route, address, phone and sales rep.", "A second person presses Verify before the customer can shop.", "On the Sales catalog, type a price for this customer only, or change the tier price.", "The customer's shop shows their price and how many are available. Press Add.", "Send order turns the cart into a draft order for sales to approve.", "Open orders shows the assigned rep on each order, with Approve, Edit and Deny."] },
  { id: "cart", category: "Orders", title: "Shopping cart and order summary", body: [
    "Press Add on any item and it goes into the cart. The count on the cart button at the top of the shop goes up.",
    "Press the cart button and the cart slides in from the right. Change amounts there, or press View cart & order summary. Close it with ✕, Keep shopping, or by tapping outside it. The cart is saved on the customer's account, not the device.",
    "On the cart page, change a quantity with the - and + buttons or type it in. Save for later moves a line out of the order but keeps it on the page; Move to cart brings it back.",
    "The order summary on the right is the live invoice: items, how much their prices save, the cash discount if they pay cash, and the estimated total. It updates as the cart changes. Print prints it.",
    "Stock is not held while something sits in a cart. If there is not enough, the cart says Only N left and the order cannot ask for more than is there.",
    "Pick how they will pay, add a note, and press Place order. There is no extra review step. The order goes to Open orders for sales to approve. Saved for later items stay behind.",
  ] },
  { id: "customer-page", category: "Orders", title: "Customer page: shopping for a customer on the phone or at the counter", body: [
    "Sales and admins have Selling → Customer page. Pick a customer (your own customers are listed first) and you see the shop exactly as they see it, with their prices.",
    "You build your own cart for that customer. It is separate from the customer's own online cart, and each customer has their own cart for you.",
    "If the customer already has items in their online cart, a bar says so. Press Pull in their online cart to add those items to yours. Their own cart is left as it was.",
    "Orders you place from the Customer page are approved right away and go straight to Ready to pull. They do not wait in Open orders.",
    "Once it is placed, choose what to do next: Go to invoice opens the order page (mark it MUST CHECK, set how it is paid, print box labels and so on), Pull ticket opens its pull ticket PDF, or Keep shopping starts another order for the same customer.",
  ] },
  { id: "pdf-printouts", category: "Settings", title: "PDF printouts: viewing, printing and sharing", body: [
    "Pull tickets, invoices and counter receipts, route sheets, box labels and item labels are all real PDFs. They are made fresh each time you open them, so they always show the latest details.",
    "Where to find them: Print pull ticket on an order, PDF / Print on an invoice, Receipt (PDF) after a counter sale, Route sheet (PDF) on Routing, Print box labels on an order, and Labels for item and lot labels.",
    "They open in the PDF viewer, which fits the page to your screen on a phone or a computer. − and + zoom in and out. Under the buttons you see the file name and how many pages it has.",
    "Print sends it to your printer. On a phone, Print opens the share sheet instead, where you can pick a printer, save the file or send it on.",
    "Download saves the PDF. Share (on phones and some computers) sends it to an app such as Mail or Messages. Open shows it in a new tab with your browser's own PDF viewer.",
    "Long pull tickets and invoices carry on over more pages, with the header and column headings repeated and page numbers at the bottom. An invoice prints a Customer copy and an Office copy, one after the other.",
    "Labels are made at the label size set under Settings → Printing, or laid out on letter or A4 paper with dashed cut lines when you use a regular printer. Print them at 100% (actual size), with no fit to page.",
    "Everything prints in black and white whatever colours the app is using. To change what a printout shows or where things sit, see PDF editor: laying out printouts.",
  ] },
  { id: "pdf-editor", category: "Settings", title: "PDF editor: laying out printouts", body: [
    "The PDF editor is where an admin decides how every printout looks. Open Settings → Customize printouts and scroll to PDF layouts. Other roles can't change layouts, but everyone's printouts use the saved one.",
    "Pick a printout with the tabs at the top: Pull ticket, Invoice, Route sheet (all on letter paper), Box label and Item label (label printer). Each one has its own layout. The hint under the tabs says what the printout is for and, for labels, the size it is laid out at.",
    "The page in the middle is drawn with sample data, so you can see how a real one will look. Tap anything to select it. Drag it to move it, and drag the blue square on its corner to resize it. Arrow keys nudge the selected item one point at a time; hold Shift to move ten.",
    "The panel on the right changes the selected item. Text items have the words (with Insert a field…), text size, colour, Bold, Italic, Typewriter (a fixed-width font, good for codes), CAPITALS and alignment (left, centre, right). Lines and boxes have line thickness and fill. Left, Top, Width and Height set the exact position in points (72 points to an inch).",
    "Fields are details filled in for each printout. They are written in curly brackets, for example {so.number} for the order number or {inv.due} for the due date. You can mix them with your own words, such as Order {so.number} for {so.customer}. + Field… adds a field on its own; Insert a field… adds one where you are typing. Each printout has its own list: the pull ticket has the customer, ship date, line count, order note and box labels printed; the invoice has bill to, deliver to, terms, resale certificate and every total; the route sheet has the day, route code, driver and stops; labels have the item, SKU, code, customer, address, box number and route.",
    "The toolbar adds things: + Text (your own words), + Line, + Box, + Signature (a signature line with a name under it), + Logo / picture (a PNG or JPG; adding a second logo replaces the first), and + Barcode (it starts with the order or invoice number; any field or text can become a barcode). Remove deletes the selected item.",
    "The list of lines (the items on a pull ticket or invoice, the stops on a route sheet) is a table. Tap it to choose its columns. Tick which columns show, rename a heading by typing over it, set the width share (each column gets its share of the table's width) and move a column earlier or later with the arrows. Text size in the list sets the size of every row.",
    "Below the lines: set Place to Below the lines for anything that should follow the list, like the totals, signature lines or the MUST CHECK box. It moves down as the list gets longer, and goes onto a new page if it doesn't fit. On the page keeps it in a fixed spot. A dashed guide on the page shows where the list ends in the sample.",
    "Pages: First page, Every page, or After the first. Page numbers ({page} of {pages}) and repeated headers usually go on every page; a shorter header can go on later pages only. Items that only print after the first page look faint on the canvas.",
    "Show only when it has a value: pick a field and the item only prints when that field isn't empty, for example the order note, the resale certificate, or the delivery address on an invoice. On the pull ticket, The order is marked MUST CHECK shows the MUST CHECK box only on orders that have it.",
    "Hide it keeps something off the printout without deleting it, and Show it brings it back. The On this printout list under the panel names everything on the page (if set means it has a show-when rule) with a Shown / Hidden switch, which is the easiest way to find small or faint items.",
    "Labels: the layout is drawn at a set size and scaled to the label size you print, so one layout works for any label printer. If your label size is different, Lay out at my label size redraws the canvas at your size so you can arrange it exactly.",
    "Undo (or Ctrl+Z) takes back your last changes, up to 50 of them. Preview PDF makes the real PDF with sample data and opens it in the viewer, so you can check pages, fonts and spacing before anyone prints. Unsaved changes are marked beside the tabs.",
    "Save layout stores it for everyone; every printout made from then on uses it. Back to the original layout throws away your layout for that printout and goes back to the one the app came with. Saved layouts are checked when saved, so a broken one can't be stored.",
    "Company details (business name, address, phone and footer) and the invoice wording (terms, note and the names of the two copies) are at the top of the same page and fill in the business and invoice fields on every printout.",
  ], images: ["Pick a printout, then tap anything on the page to change it in the panel on the right.", "The toolbar adds fields, text, lines, boxes, signatures, a logo or a barcode.", "Tap the list of lines to choose its columns, headings and widths.", "Show only when it has a value, Place and Pages for the selected item.", "Preview PDF shows the printout as a real PDF with sample data."] },
  { id: "returned-labels-routes", category: "Orders", title: "Sending an order back, box labels and route sheets", body: [
    "Pulled orders get checked before they are invoiced. If something is wrong, Delivery/Order Management types what sales needs to fix in the box on the order and presses Send back to sales. The order moves to Sent back to sales and shows the note.",
    "Sales then changes the quantity on each line to what was really pulled. A quantity can only go down. The difference goes back on the shelf, into the same lots it came from, and the cost updates. Set a line to 0 to take it off. Press Save and send to Delivery/Order Management and it returns to Pulled for the check. If sales cannot fix it, use Returns & credits instead.",
    "Box labels: once an order is ready to pull, type how many boxes on the order page and press Print box labels. Each label carries the shop name, the address it is going to, the route, Box 1 of 3 style numbering and the same barcode as the pull sheet. They print on the label printer chosen in Settings. The count is saved and shows on the pull sheet in the line Box labels printed.",
    "Invoices: Print an invoice and you get two copies, a Customer copy and an Office copy, one after the other.",
    "Route sheets: Routing groups orders by the customer's 3 letter route. Pick a route code at the top to see only those orders. Scan each invoice in, press Closest to farthest, then print. Every stop shows how many boxes to expect, from the label count, and the bottom of the sheet totals the boxes. Each route code keeps its own sheet for the day.",
  ], images: ["Delivery/Order Management sends a pulled order back to sales with a note.", "Sales sees the note and lowers the quantities. The difference goes back on the shelf.", "Type how many boxes, then print the labels.", "One label per box: shop, address, route, Box 1 of 3, and the order barcode.", "The pull sheet shows how many box labels were printed.", "Pick a route code to see only that route's orders.", "The route sheet shows boxes expected per stop and in total.", "Print gives a customer copy and an office copy."] },
  { id: "passwords-printouts", category: "Settings", title: "Passwords, resets and customizing printouts", body: [
    "Changing your password: open Settings, find Password, type the current one and the new one twice. This works for everyone, customers included.",
    "Forgot password: the sign-in page has a Forgot password link. The customer types their username. If the customer account has an Email, a reset link goes to that address. If it has no email, the customer's request appears for sales and admin under Customer logins (with a number beside it in the menu). Press Approve, and the customer then opens My reset was approved on the same page and chooses a new password. An approval stays valid for 24 hours and works once. The page gives the same answer whether or not the username exists.",
    "Password hint (customers): in Settings, Password, a customer can add an optional hint. After a wrong password the sign-in page offers Show password hint. Anyone who types the username can see the hint, so the app refuses hints that contain the password.",
    "Sending reset links needs the server set up with a site address and an email service key. Without them, every reset goes through approval.",
    "Customize printouts (admin only, under Settings): set the business name, address, phone and footer, and the invoice's copy titles, terms and note. Below that, PDF layouts lets you lay out each printout: see PDF printouts and the layout designer.",
    "Printers: under Settings, Printing, type the name of your label printer and your regular printer as they appear in the print dialog. Browsers cannot list or pick printers by themselves, so the name is a reminder: box labels say to choose the label printer, and other printouts show the regular printer's name on the Print button. The names are saved on that computer only, so each workstation can have its own.",
  ] },
  { id: "must-check", category: "Orders", title: "MUST CHECK", body: [
    "Sales reps can flag any order MUST CHECK with a button at the top of the order, at any status.",
    "The red MUST CHECK box shows on the order and prints in the top right of the pull ticket with a line underneath for a signature.",
    "Remove it with the same button once the check is done.",
  ] },
  { id: "delivery-address", category: "Orders", title: "Delivery address vs location address", body: [
    "A customer has a location address (where the business is) and an optional delivery address.",
    "A new order copies the delivery address, or the location address if there is no delivery address. You can change it on that one order under Details → Deliver to.",
    "Invoices show both: Bill to · location, and Deliver to. They also show which shop the order ships from (set Ships from on the order if you have more than one shop).",
    "Routing uses the order's Deliver to address, so fix it on the order if a stop looks wrong.",
  ], images: ["Deliver to on a draft order. Change it here when this delivery goes somewhere else.", "An invoice with Bill to, Deliver to and Ships from."] },
  { id: "pull-ticket-guide", category: "Orders", title: "Reading and signing a pull ticket", body: [
    "Open an order that is Ready to pull and tap Print pull ticket. It is one letter-size page, black and white.",
    "The header shows the order number, customer, ship date and number of lines. A red MUST CHECK box with a signature line prints in the top right when the order has that flag.",
    "Lines are grouped by the shop section where the stock is now, A to Z inside each section. Each line names the lot to pull from. Anything short on stock is listed under Not in stock with how much is missing.",
    "Each line has a tick box and blank Pulled and Packed lines. At the bottom are Pulled by and Packed by signature lines. Fill them in and hand the ticket back to Delivery/Order Management.",
  ], images: ["The ticket header, with order, customer and ship date.", "A section of the ticket with the tick box, lot, quantity, and Pulled and Packed lines.", "The Pulled by and Packed by signature lines at the bottom."] },
  { id: "routing-day", category: "Orders", title: "Routing: build a day's delivery route", body: [
    "Open Selling → Routing. Pick the Delivery day. The list is every Completed or Invoiced order that ships that day from the chosen shop. The route starts at the shop's address and ends at the last stop; there is no trip back.",
    "Tap Closest to farthest to sort the stops by distance from the shop, or use the up and down arrows to set the order yourself. Remove takes an order off the route and it moves to Not on this route, where Add puts it back.",
    "Under each stop you can see the delivery address and the miles from the stop before it. The total shows the number of stops, miles and a driving-time estimate.",
    "Open in Google Maps opens the whole route in Google Maps with every stop in order. More than 10 stops are split into several links, each one starting where the last ended.",
    "Type the driver's name, then Save route to keep the order. Route sheet (PDF) makes the driver's sheet as a PDF, with a tick box and a signature line beside each stop.",
    "You can also add orders by scanning an invoice barcode. See Adding orders to a route by scanning the invoice.",
    "In the full app the first time an address is used it is looked up with Google and remembered. This needs the Google Maps key (see Setting up Google Maps for Routing). In the demo the map positions are made up.",
  ], images: ["Pick the delivery day. The orders that ship that day are listed.", "Closest to farthest sorts the stops by distance from the shop.", "Use the arrows to move a stop up or down.", "Open in Google Maps opens the whole route.", "Print route sheet prints the driver's copy."] },
  { id: "maps-setup", category: "Settings", title: "Setting up Google Maps for Routing (admin)", body: [
    "Routing needs a Google Maps key so it can find addresses and open real roads. Without it you can still order stops by hand and use the Open in Google Maps links.",
    "In Google Cloud (console.cloud.google.com) create a project and attach billing. Google asks for a card, but this use normally stays within the free monthly credit.",
    "Under APIs & Services → Library enable Geocoding API and Routes API. Under Credentials create an API key.",
    "Edit the key: under Application restrictions choose Websites and add your site's address. Under API restrictions allow only those two APIs. This stops anyone else using the key.",
    "In the app open Settings → Maps & routing (admins only). Paste the key and save. Also fill in each shop's address on that page; the route starts there.",
  ], images: ["Maps & routing settings: paste the key here.", "Each shop's address is the starting point of its routes."] },
  { id: "gif-setup", category: "Messages", title: "Setting up GIF search in Messages (admin)", body: [
    "GIF search uses GIPHY. Without a key people can still paste a GIF link into a message.",
    "Go to developers.giphy.com, sign in, choose Create an App and pick API (not SDK). Copy the key it gives you.",
    "Add it where the app is hosted as an environment variable named GIPHY_API_KEY, then redeploy. On Vercel that is Project → Settings → Environment Variables.",
    "New GIPHY keys start in a limited beta mode, which is fine for a small team. Apply for production access later if you hit the limit.",
    "Then the GIF button in a chat opens a search box.",
  ], images: ["The GIF button is next to the message box."] },
  { id: "scan-box-return", category: "Stock", title: "Returning a received box to the vendor (scan the box label)", body: [
    "Every lot you receive gets a label with a barcode (Lot labels on the purchase order, or Labels). Print one label per physical box; they all carry the same lot code.",
    "To start a return, scan the box label on the Scan page, with a handheld scanner or the Camera button on a phone. The lot page opens.",
    "Under Return to vendor you will see the vendor and their email, the purchase order, product, quantity received, cost, lot code and received date.",
    "Tap Email vendor to open a draft addressed to the vendor with all of that filled in. Add the reason and send it from your mail app. Copy details copies the same text.",
    "If the vendor has no email, add it on the vendor page first. Credits you receive from the vendor are not tracked in the app yet.",
  ], images: ["Lot labels on a received purchase order print a barcode label for each lot.", "Scan the box label (or type its code) on the Scan page.", "Return to vendor on the lot page. Email vendor opens the draft."] },
  { id: "scan-route", category: "Orders", title: "Adding orders to a route by scanning the invoice", body: [
    "Every invoice prints a barcode of its invoice number at the bottom right.",
    "On Routing, scan that barcode (scanner or Camera) to add the order to the day's route. Scanning an order number works too.",
    "Only Completed or Invoiced orders can be added. An order that ships on a different day is added and marked with its ship date.",
    "Scanning an order that is already on the route just tells you so. Tap Save route to keep the changes.",
  ], images: ["The invoice barcode, bottom right of every invoice.", "Scan the barcode into the box on Routing."] },
  { id: "pull-order", category: "Stock", title: "How stock is chosen when an order is pulled", body: [
    "Mark pulled takes stock from the oldest lots first (by received date), so older flowers go first.",
    "Mark pulled from chosen lots lets you pick exact lots or scan them. The quantities must add up to the line.",
    "If there isn't enough stock, the order is blocked and nothing is taken. The pick ticket lists what is short.",
  ] },
  { id: "lots", category: "Stock", title: "Lots, units and costs", body: [
    "Every delivery creates a lot with a code, received date, expiry date, location and cost.",
    "Products have a base unit (usually the stem) and other units such as bunch or box, each with a conversion. Stock is always counted in the base unit.",
    "Cost uses FIFO: an order's cost is the cost of the lots it was pulled from. Margin on an order is price minus that cost.",
    "Landed cost includes freight shared across the lines of a purchase order.",
  ] },
  { id: "shrink", category: "Stock", title: "Shrink, adjustments and counts", body: [
    "Shrink is stock that is lost, damaged or thrown out. Record it with a reason so reports show where losses come from.",
    "An adjustment corrects a lot's quantity after a count.",
    "Resellable returns go back into the lots they came from. Returned items marked not resellable are written off as shrink automatically.",
  ] },
  { id: "floor-plan-faq", category: "Stock", title: "Shop floor plan basics", body: [
    "Each shop has its own layout and its own sections. Sections can be any shape.",
    "Sizes are in feet, based on the floor width you enter. The grid shows foot squares.",
    "A product's home is the section where it belongs. Stock sitting somewhere else is shown so you can find and move it.",
    "The pull ticket groups lines by the section the stock is in right now.",
    "Moving a section to another shop clears its old shape and the product homes that pointed to it.",
  ] },
  { id: "sections-shelves", category: "Stock", title: "Sections and shelves inside a location", body: [
    "A location (Cooler 1) can hold sections (Rack A, Bucket row), and each section can have shelves (1, 2, 3 or Top, Middle, Bottom).",
    "Add one: Location in shop → Edit layout → + Add section. Pick the location, or + New location…, name the section and list its shelves. 1-4 makes shelves 1 to 4. It appears on the plan inside its location; drag and resize it like any area.",
    "Tap a section to edit, rename or delete it. Tap a location to rename it or add a section to it.",
    "Receiving: next to each line's location, pick the section and shelf. It starts at the item's usual spot in that location; changing the location changes the choices. Left on No section, the usual spot is used when the stock goes into its home location.",
    "Where stock sits: on a lot's page, set Section and shelf. Moving stock to another location clears it.",
    "An item's usual spot: on the item's page, under its home area, set Usual section and shelf.",
    "Pull tickets show Section · Shelf for each line: the stock's own spot, else the item's usual spot when the stock is in its home location. Lines are sorted by section, then shelf.",
  ] },
  { id: "direct-ship-faq", category: "Stock", title: "Direct ship and receiving part of an order", body: [
    "A direct-ship purchase order is bought for one customer. Set Direct ship for on a standing order (every delivery it plans follows it, apart from ones you have edited) or on a single purchase order when you create it or in its Details. Choose Not direct ship to turn it off.",
    "Direct-ship orders have a purple Direct ship → customer badge on Purchasing, Receiving, the shipment and the standing order.",
    "Receiving one gives two buttons. Receive to [customer]'s order receives the stock as usual (lot, landed cost, location, section and shelf) and makes a new Ready to pull order for that customer at their usual prices, with only what came in. Receive into our stock instead receives it like any other purchase order.",
    "Stock received to a customer's order is held for that order. Other orders, pull tickets and hand-picking skip it, and its own order takes it first. The hold ends when the order is marked pulled or cancelled. Available stock in the shop already leaves it out.",
    "Every receipt makes its own order, so if part comes now and the rest later, the customer gets two orders. The purchase order lists the orders it made, and each order's note says which purchase order it came from.",
    "On a shipment, each direct-ship purchase order has a ticked Direct ship box. Untick it to receive that one into stock instead.",
    "All, Some or None: every line being received starts at All (everything still due). Choose Some and type how many came, or None if it didn't come. The line under the table sums it up. Lines set to None are greyed out.",
    "Whatever didn't come stays due on the purchase order, which shows Partially received. Receive the rest when it arrives, or Close short when nothing more is coming.",
    "A shipment that came in short stays open as Arrived (partly received), with only the missing lines left to receive. It finishes by itself once those are received, moved to another shipment or closed short.",
  ] },
  { id: "documents", category: "Documents", title: "Documents: what's there and who can use it", body: [
    "Documents is in the main menu for every staff role. It has three tabs: Word editor for writing, Send for signing for getting PDFs signed, and To sign for anything sent to you.",
    "Word editor documents are private: only the person who wrote one can open it. See Word editor: writing and formatting documents.",
    "Send for signing lets anyone on staff upload a PDF, mark where people sign or type, and email it for signature. The PDFs and the list of sent requests are shared by the whole team, so anyone can prepare, send or follow up, and each request shows who sent it. See Signature requests: preparing and sending a PDF.",
    "To sign lists documents sent to your account email, with Open and sign on the ones still waiting. Customers and people outside the business sign from the emailed link instead. See Signing a document.",
  ] },
  { id: "word-editor", category: "Documents", title: "Word editor: writing and formatting documents", body: [
    "Open Documents → Word editor. Your documents are listed on the left, newest first, with their word count and when they were last changed. Tap one to open it. « hides the list to give the page more room and ☰ brings it back; on a phone the list hides itself once you open a document.",
    "+ New document starts a blank page called Untitled document. Click the title at the top of the page to rename it. ✕ beside a document in the list deletes it after asking; this can't be undone.",
    "Import .docx brings in a Word file. Headings, bold, italic, underline, lists, links and most text formatting come across; things the editor doesn't have, such as tables, comments and tracked changes, are left out. The new document is named after the file.",
    "Export .docx downloads the open document as a Word file, ready to open in Microsoft Word, Google Docs or Pages, or to attach to an email.",
    "Paragraph style: Normal, Heading 1, Heading 2, Heading 3 or Quote. Font: Default, Calibri, Arial, Georgia, Times New Roman, Garamond, Verdana or Courier New. Size: 9 to 48 point. Fonts and sizes that came in from a Word file stay in the list for that text.",
    "Bold, Italic, Underline and Strikethrough work on selected text, or on what you type next. Keyboard shortcuts: Ctrl+B, Ctrl+I, Ctrl+U, Ctrl+Z to undo and Ctrl+Y to redo (⌘ instead of Ctrl on a Mac). A tells you the text colour and opens a colour picker.",
    "Link: select some words, tap 🔗 and type the web address. To take a link off, tap 🔗 again and clear the address. Web addresses you type become links by themselves.",
    "Alignment: left, centre, right or justified, for the paragraph you are in. Lists: bulleted or numbered; Increase indent and Decrease indent move a list item in or out a level. Horizontal line adds a divider. Clear removes formatting from the selected text (styles, fonts, colours, links, alignment) and turns headings back into normal paragraphs.",
    "Saving is automatic, about a second after you stop typing. The note beside the title says Saved, Unsaved changes, Saving… or, if the connection drops, Couldn't save — retrying when you type. Ctrl+S (⌘+S) saves straight away. If you try to close the page with unsaved changes, the browser asks first.",
    "Open in two windows: if the same document is saved from another window or device, this copy stops saving so it can't overwrite that work, and a bar says Changed in another window. Tap Reload to get the newest version.",
    "The bar at the bottom shows the words and characters in the document and how many words you have added today.",
    "Writing diary (the button beside Export .docx) keeps a log of your writing. Each entry is a day you wrote, with when you started and stopped and the net number of words added or taken away that day, including edits to older parts of the document. An imported Word file gets its own Imported entry.",
    "Highlight sections colours the text by the day it was written, matching each entry's colour swatch. Tap an entry to jump to its text. Text you edit later keeps the colour of the day it was first written. Start new day closes the current count and starts a new one, for example when a new writing session begins on the same day.",
    "The diary and the highlights are only on screen. They are never printed or exported, and Clear never removes them. The diary and highlight choices are remembered on that device.",
    "Privacy: documents are stored with your account and nobody else can open them, admins included. To share a document, use Export .docx and send the file.",
  ], images: ["The toolbar: style, font, size, bold, italic, underline, colour, link, alignment, lists and Clear.", "The writing diary lists each day's words; Highlight sections colours the text by day.", "+ New document, Import .docx and the list of your documents."] },
  { id: "signature-requests", category: "Documents", title: "Signature requests: preparing and sending a PDF", body: [
    "Open Documents → Send for signing. The Documents tab lists the PDFs your team has added, with how many fields and pages each has. The Sent tab lists every request sent, who sent it and whether it has been signed. Both lists are shared by everyone on staff.",
    "+ Add PDF uploads a PDF of up to 10 MB and opens it in the field editor. A fillable PDF has its own form fields turned into boxes. Otherwise boxes are suggested next to words such as Signature, Sign here, Initial, Printed name, Date and Title. Check the suggestions and delete any you don't want.",
    "Adding a field: tap + Signature, + Initials, + Checkbox or + Text, then tap the page where it goes. The note under the toolbar reminds you what you are placing. Signature boxes are blue, initials purple, checkboxes gold and text boxes green.",
    "Moving and sizing: drag a box to move it, and drag the white square on its corner to resize it. − and + zoom the pages so small boxes are easier to place. Tap the page away from any box to deselect.",
    "Changing a box: tap it to open its settings at the bottom. Type switches between Signature (they sign or stamp their name), Initials, Checkbox and Text field (they type). Label is what the box is for, such as Date or Printed name; the signer sees it as a hint. Fill (white) covers whatever is printed under the box. Underline shows it as a line instead of a box. Delete box removes it.",
    "Tap Save when the fields are right, then ✕ to close. You can come back with Mark fields at any time. Send to… stays greyed out until the document has at least one field.",
    "Sending: tap Send to…, type the signer's email and tap Send. One request goes to one person; to have two people sign, send it twice. The email comes from your account (your name and email are shown to the signer), so replies come back to you.",
    "Who signs, and how they are checked: if the email belongs to a DKaydent login, that person must be signed in to that account to open it, and it appears in their To sign tab. Anyone else must type the exact email it was sent to before the document opens.",
    "Email: requests and Signed notices are sent through the same email setup as password resets (RESEND_API_KEY). Without it, sending still makes the request and shows the signing link with Copy link, so you can send it yourself by text or your own email.",
    "Following up: the Sent tab shows Waiting with the time it was sent, or Signed with the time it was signed. The person who sent it gets an email when it is signed, and the tab shows Sent (1 new) until someone downloads the signed copy. Download gets the signed PDF. Withdraw cancels an unsigned request so the link stops working. Remove deletes a signed copy from the list.",
    "The signed PDF has everything the signer filled in drawn onto the pages, plus a certificate page at the end: the document, who signed and how they were checked (signed in to their account, or confirmed by email), who sent it, the signer's IP address and device, the time in UTC and a request ID.",
    "Deleting a document removes it and its field layout from the Documents list. Requests already sent keep working, and signed copies stay in the Sent tab.",
  ], images: ["Place Signature, Initials, Checkbox and Text boxes on the page.", "Tap a box to change its type, label, fill or underline.", "Send to… emails the request; without email set up you get a link to copy.", "The Sent tab shows who has signed, with Download for the signed PDF."] },
  { id: "signing-documents", category: "Documents", title: "Signing a document", body: [
    "From a teammate: open Documents → To sign. Documents sent to your account email are listed with who sent them and when. Tap Open and sign. Because you are signed in, there is no extra check.",
    "From an emailed link: open the link. If it was sent to a DKaydent login, you are asked to sign in with that account first. Otherwise, type your full name and the email address it was sent to and tap Open document. A different email address is refused.",
    "Your signature: type your full name at the top and it is used as a handwritten-style signature. To draw it instead, tap Draw signature, sign with a finger or mouse, and tap Use this (Clear starts again). Initials are filled in from your name; type over them or tap Draw initials.",
    "Filling it in: tap each Sign here box to put your signature in it, and each Initials box for your initials. Type in the text boxes (the grey hint says what goes there). Tap a checkbox to tick it, and again to untick it. − and + zoom the pages.",
    "Tap Submit when you are done. Every signature and initials box has to be filled first. After submitting you see All done, and Download signed PDF saves your copy. The sender is emailed that it was signed.",
    "Opening the link again after it is signed shows This document has already been completed, with the download button. A link the sender has withdrawn no longer opens.",
    "The signed copy ends with a certificate page that records your name, how you were checked, your IP address and device, and the time, so the signature can be checked later.",
  ], images: ["Type or draw your signature and initials at the top, then tap each box.", "Submit, then download your signed copy."] },
  { id: "labels-faq", category: "Stock", title: "Label printing", body: [
    "Choose Label printer for a roll or thermal printer, or Regular printer for plain paper, in Settings → Printing.",
    "That choice is saved on the computer you are using, so each workstation can use its own printer.",
    "If labels print with extra blank pages, check the printer's paper size is set to the label size in your print dialog.",
    "Every label shows the day it was printed.",
  ] },
  { id: "invoices-faq", category: "Money", title: "Invoices, tax and terms", body: [
    "Terms come from the customer (Net 30 by default) and set the due date.",
    "Sales tax is typed when you create the invoice. Leave 0 for resale-exempt customers; the resale certificate number is kept on the customer and printed on the invoice.",
    "Void an open invoice to correct the order; it goes back to Completed so you can invoice again. Paid invoices, or invoices with payments, can't be voided until the payments are voided.",
  ] },
  { id: "card-fee", category: "Money", title: "Card processing fee", body: [
    "Orders paid by card get a card processing fee, 2.5% unless an admin changes it under Settings → Card processing fee. 0 turns it off.",
    "The fee is worked out on the subtotal plus tax and shows as its own line on the invoice. Cash and check orders don't get it.",
    "How an order is paid comes from the cart (Pay by), or from Pays by under Details on the order page. It can change until the order is invoiced; after that, void the invoice to change it.",
    "Before invoicing, the order page and cart show the fee on the subtotal; the invoice works it out again once tax is added.",
    "Counter sales charged on a terminal include the fee. Paying cash or check at the counter doesn't.",
    "Each invoice keeps the rate it was made with, so changing the setting doesn't change old invoices.",
  ] },
  { id: "payments-faq", category: "Money", title: "Deposits, partial payments and terminals", body: [
    "Money taken before invoicing is a deposit and is applied to the invoice when it is created.",
    "Partial payments keep the invoice open and show the balance.",
    "Card payments can be sent to a payment terminal. If a payment is declined it stays on record as declined and does not count.",
    "Voiding a payment reopens a paid invoice.",
  ] },
  { id: "returns-faq", category: "Money", title: "Returns and credits", body: [
    "You can only return what was sold, and not more than what is still returnable on the line.",
    "The credit is at the price on the order plus the invoice's tax rate.",
    "A credit starts Open. Mark it Applied when it is used on a later invoice, or Refunded when money is returned.",
  ] },
  { id: "recurring-faq", category: "Orders", title: "Recurring orders", body: [
    "A recurring order creates planned draft orders on the days you choose.",
    "Planned orders stay under Recurring (planned) until a week before they ship, then join the normal list.",
    "Editing a planned order marks it as edited, and it is left alone if you later change the series.",
    "Skipping a planned order cancels just that one.",
  ] },
  { id: "web-store-faq", category: "Web store", title: "How the web store connection behaves", body: [
    "The website is the source of truth for stock numbers. Counts come in as the supply figure; what you pull in the app is subtracted from them.",
    "Each web order creates one Ready to pull order, even if the website sends it twice.",
    "A cancelled web order cancels the matching order only if it hasn't been pulled yet.",
    "Use Sync now any time, and check the log on the Web store page if a number looks wrong.",
  ] },
  { id: "messages-faq", category: "Messages", title: "Messages: channels, privacy and GIFs", body: [
    "Team channels are shared: Everyone, Sales, Warehouse and Buyers. You only see the channels for your role (admins see all).",
    "Direct chats and groups are private to the people in them. Admins can't read them.",
    "Messages are kept; there is no edit or delete yet.",
    "GIF search needs a GIPHY key (see Setting up GIF search in Messages). Without it you can paste a GIF link.",
    "Messages arrive live. If your host doesn't support live updates, the page refreshes every 5 seconds.",
    "New chat starts a direct chat or a group. A number beside a chat, and beside Messages in the menu, is what you haven't read.",
  ], images: ["New chat starts a direct chat or a group.", "GIF opens the GIF search (or asks for a link if no key is set up)."] },
  { id: "appearance", category: "Settings", title: "Appearance and printing settings", body: [
    "Settings → Customize page sets the colour palette and light, dark or follow-my-device. There are 10 ready-made palettes, including High contrast (stronger borders and extra-dark text). It is saved on that device.",
    "Make your own: pick one colour, type a hex code, or choose a photo and tap one of the colours found in it. The rest of the theme is worked out for you, with text kept easy to read in light and dark. The photo is read in your browser and is not uploaded or kept. Your theme is saved on that device only; Go back to the default colours clears it.",
    "Font: pick any of 12 open-source typefaces for yourself, including OpenDyslexic (made to help people with dyslexia), Lexend and Atkinson Hyperlegible (both made for easier reading). Choose Palette default to go back. Each person's choice is saved on their own device.",
    "Invoices, labels and pull tickets always print in black and white whatever palette is chosen.",
    "Printing settings (label or regular printer) are saved per computer.",
  ], images: ["The Font section of Settings → Customize page. Tap a font to use it right away."] },
  { id: "help-guide", category: "Settings", title: "Using Tutorials and the Knowledge base", body: [
    "Settings → Tutorials has step-by-step guides for the main jobs. Each step has a picture with an orange box and arrow showing what to tap or fill in.",
    "Tap a name at the top of the page to jump to a guide. Links beside a step open the right page.",
    "Settings → Knowledge base explains how things work. Search finds articles and tutorials, best match first, and marks the matching words; it understands plurals and word endings (shelves finds shelf). Pick a category to narrow it.",
    "Anyone on the team can tap + Write an article to add what they know: a title, a category (or a new one) and the text, one paragraph per point. You can edit or remove your own articles.",
    "Admin can edit or remove any article, hide one (Show hidden brings it back into view for admin), and reword a built-in article. Restore original puts a built-in article back the way it shipped.",
    "Tutorials show the demo's screens, so colours and fonts may differ slightly from yours.",
  ], images: ["Tutorials and Knowledge base are in the Help part of Settings.", "Every step has a picture with an arrow.", "Search the Knowledge base by any word."] },
  { id: "phone", category: "Settings", title: "Using the app on a phone", body: [
    "Tap the menu button at the top left to open the slide-in menu. Groups (Buying, Stock, Selling, Reports & data, Settings) fold open and closed, and the app remembers which are open.",
    "Floor plans, labels and pull tickets work on a phone, but print from a computer when you can.",
    "Messages opens on the chat list on a phone. Tap a chat to open it and the arrow to go back.",
    "There are two modes, like Amazon's app and desktop site. Phones open in Mobile mode, computers and tablets in PC mode.",
    "Mobile mode uses the phone layout with tabs along the bottom: customers get Shop, Cart and Account; staff get Home, two pages for their job (for example Counter and Orders for sales, Scan and Inventory for the warehouse) and Messages. Menu opens the full menu.",
    "Mobile mode works even if the phone's browser asks for the desktop site: the page is laid out at phone width, so text stays a normal size.",
    "To see the full desktop layout on a phone, open Menu and tap Desktop site. Tap Mobile site in the menu to go back. The choice is remembered on that phone.",
  ] },
  { id: "import-export", category: "Settings", title: "Import and export data", body: [
    "Reports & data → Import data brings in products, vendors and customers from CSV files. A preview shows problems before anything is saved.",
    "Export CSV buttons on lists download what you are looking at.",
  ] },
];

